&quot; + std::string(RESET); \ IC_CONFIG.prefix(prefix.c_str()); \ IC(__VA_ARGS__); \ prefix = std::string(YELLOW) + &quot;info &quot; + std::to_string(getpid()) + &quot;/&quot; + thread_id_str + &quot; | &quot; + std::string(RESET); \ IC_CONFIG.prefix(prefix.c_str()); \}#define colorBY(color, format, ...) { \ pid_t tid = syscall(SYS_gettid); /* 获取系统级 TID */ \ std::string thread_id_str = std::to_string(tid); \ std::string prefix = std::string(color) + format + &quot; &quot; + std::to_string(getpid()) + &quot;/&quot; + thread_id_str + &quot; | &quot; + std::string(RESET); \ IC_CONFIG.prefix(prefix.c_str()); \ IC(__VA_ARGS__); \ prefix = std::string(YELLOW) + &quot;info &quot; + std::to_string(getpid()) + &quot;/&quot; + thread_id_str + &quot; | &quot; + std::string(RESET); \ IC_CONFIG.prefix(prefix.c_str()); \}#define tIC(...) { \ pid_t tid = syscall(SYS_gettid); /* 获取系统级 TID */ \ std::string thread_id_str = std::to_string(tid); \ std::string prefix = std::string(YELLOW) + &quot;info &quot; + std::to_string(getpid()) + &quot;/&quot; + thread_id_str + &quot; | &quot; + std::string(RESET); \ IC_CONFIG.prefix(prefix.c_str()); \ IC(__VA_ARGS__); \} 打开代码行数等信息显示，默认false 1IC_CONFIG.include_context(true); 复杂结构体无法打印，编译会失败，需要注册 常见简单打印基本打印12345678#define debug(...) printf(__VA_ARGS__)// or complex usage of preprocessor directives in C++#if !defined(CC_USED__) || CC_USED_ABI_VERSION != __GXX_ABI_VERSION \ || __GNUC_MINOR__ &lt; CC_USED_MINOR__ \ || __GNUC_MINOR == CC_USED_MINOR__ &amp;&amp; __GNUC_PATCHLEVEL__ &lt; CC_USED_PATCH_LEVEL #error This kit requires gcc 3.2.x or 3.3.x with a version &gt;= compiler version of the kit #endif cout 、cerr、clog C++中都是标准IO库中提供的输出工具： cout：写到标准输出的ostream对象； cerr：输出到标准错误的ostream对象，常用于程序错误信息；cerr不经过缓冲而直接输出，一般用于迅速输出出错信息 clog：也是输出标准错误流; clog中的信息存放在缓冲区,缓冲区满或者遇到endl时才输出 1234567891011121314151617181920212223242526272829Lock iolock;#if 0# define LOCKED(...) { ScopedLock sl(iolock); fflush(stderr); __VA_ARGS__; fflush(stderr); }# define LOGID() fprintf(